window.kbPageData["views/entry/k-a8a2fb78a556548e"] = {"key":"entry/k-a8a2fb78a556548e","state":{"route":"entry/k-a8a2fb78a556548e"},"node":{"id":"k-a8a2fb78a556548e","mode":"k","title":"医疗卫生强基工程","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#22","政治理论必刷100题#67"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["employment"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["公共管理","社会治理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["政治理论专项","时政"]},"eventTags":[{"year":2025,"title":"医疗卫生强基工程","slug":"a84d36564189"}],"directorySummary":"医疗卫生强基工程是通过推动优质医疗资源下沉、加强基层薄弱专业建设，提升县级医院和城乡基层医疗卫生机构服务能力的工程。","review":{"title":"医疗卫生强基工程","type":"制度与规则","definition":"医疗卫生强基工程是通过推动优质医疗资源下沉、加强基层薄弱专业建设，提升县级医院和城乡基层医疗卫生机构服务能力的工程。","explanation":"2024年12月中央经济工作会议将实施该工程纳入2025年保障和改善民生任务。2025年6月，中共中央办公厅、国务院办公厅印发的《关于进一步保障和改善民生 着力解决群众急难愁盼的意见》明确了三项下沉要求。城市医疗资源向县级医院和城乡基层下沉，逐步实现紧密型县域医共体建设全覆盖。高水平医院的人员、服务、技术、管理等向基层医疗卫生机构下沉，并推进城市医联体建设。高水平医学人才向县级医院下沉，重点强化基层医疗卫生机构的薄弱专业。","basis":"据关联原题和解析编释。","references":[],"related":["k-abbc38c6242df627"],"domain":"公共管理","examFocus":{"政治理论必刷100题#22":"对照2024年中央经济工作会议的任务划分，判断题中就业、教育、医疗生育、绿色产业和外贸举措各归哪项任务。","政治理论必刷100题#67":"对照题引《意见》，逐项核对医疗卫生强基工程中下沉的对象、承接机构和配套措施。"}},"aspects":[{"title":"列入2025年民生重点任务","uses":[{"unit":"Q1","role":"直接考查","use":"《政治理论必刷100题》第22题的第③项并列列出实施该工程和制定促进生育政策，两项举措均属会议部署的保障和改善民生任务。全题正确的是①②③，共3项，选B。","evidence":"实施医疗卫生强基工程，制定促进生育政策","qids":["政治理论必刷100题#22"]}]},{"title":"三项下沉的对象与去向","uses":[{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第67题要求选出不属于2025年6月《意见》所列三项下沉的内容。A、C、D分别对应城市医疗资源、高水平医学人才、高水平医院的人员及服务等下沉。B所述远程医疗服务网络及诊断模式未列入这三项，故选B。","evidence":"推动远程医疗服务网络下沉，推广“分布式检查、集中式诊断”医疗服务模式","qids":["政治理论必刷100题#67"]}]}],"sources":[{"id":"6a7f675fdb5d48b7","label":"医疗卫生强基工程","topic":"年度政府工作","category":"时政","text":"1.医疗卫生强基工程\n以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大和二十届二中、三\n中全会精神，深入学习贯彻习近平总书记关于健康中国建设的重要论述精神，落实新时代党\n的卫生与健康工作方针，坚持以基层为重点，着力强基层、固基础、保基本，织牢基层网底，\n改善基础服务条件，优化保障基本服务，加快推动从以治病为中心向以人民健康为中心转\n变，不断增强人民群众健康获得感、幸福感、安全感。\n到 2027 年，基层医疗卫生机构布局更加合理，设施条件进一步改善，基本公共卫生服\n务能力和基本医疗服务能力持续提升，力争居民 15 分钟可达最近的医疗服务点。到 2030\n年，基层医疗卫生服务体系进一步健全，人才队伍持续发展壮大，设施设备条件和数智化水\n平显著改善，基本公共卫生服务均等化和基本医疗服务均质化水平明显提升，县级及以下医\n疗卫生机构服务量占比持续提高，中西医协调发展迈向更高水平，分级诊疗体系建设取得显\n著成效，群众就近就便享有优质高效的健康服务。\n——《医疗卫生强基工程实施方案》","source":{"doc":"6cbfb01fe723bba64b75","first":10,"last":10,"page":10,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#22":{"paper":"政治理论必刷100题","n":22,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",6],"asrc":["国省考政治理论必刷100题.pdf",44],"card":"2f4edcdf47f923fd463d2460","links":[{"id":"k-a8a2fb78a556548e","role":"直接考查","why":"医疗卫生强基工程与促进生育政策均列入保障和改善民生任务。"}]},"政治理论必刷100题#67":{"paper":"政治理论必刷100题","n":67,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",21],"asrc":["国省考政治理论必刷100题.pdf",75],"card":"39b266ed8b391654d9800a11","links":[{"id":"k-a8a2fb78a556548e","role":"直接考查","why":"三个“下沉”分别涉及城市医疗资源、高水平医院的人员服务技术管理、高水平医学人才，承接范围分别为县级医院和城乡基层、基层医疗卫生机构、县级医院。"}]}},"terms":{"k-abbc38c6242df627":{"id":"k-abbc38c6242df627","mode":"k","type":"观点与论证","title":"人民健康的战略地位","qs":[],"count":2}},"references":{},"topics":[{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-a8a2fb78a556548e":[["政治理论必刷100题#22"],["政治理论必刷100题#67"]]}};
